mapper.select:
SELECT p.id AS projectId,p.project_name AS projectName,p.project_desc AS projectDesc,p.cover_url AS coverUrl, p.user_id AS ownerUserId,CASE WHEN p.user_id=#{userId} THEN 'OWNER' ELSE m.role_code END AS roleCode, p.status,w.id AS workspaceId,w.revision,w.event_seq AS eventSeq,w.node_count AS nodeCount, w.edge_count AS edgeCount,w.group_count AS groupCount,p.update_time AS updateTime FROM aid_comic_project p LEFT JOIN aid_project_member m ON m.project_id=p.id AND m.user_id=#{userId} AND m.status='ACTIVE' LEFT JOIN aid_canvas_workspace w ON w.project_id=p.id AND w.del_flag='0' WHERE p.project_type='canvas' AND p.del_flag='0' AND (p.user_id=#{userId} OR m.id IS NOT NULL) AND p.project_name LIKE CONCAT('%',#{projectName},'%') ORDER BY
p.create_time p.project_name p.update_time
ASCDESC,p.id DESC LIMIT #{offset},#{limit}

SELECT * FROM aid_canvas_object WHERE workspace_id=#{workspaceId}
AND deleted=0
ORDER BY id

mapper.update:
UPDATE aid_canvas_object SET object_version=object_version+1,content_json=#{contentJson},content_hash=#{contentHash},
    deleted=#{deleted},last_actor_user_id=#{actorUserId},lock_fence=#{lockFence},update_time=NOW()
WHERE workspace_id=#{workspaceId} AND object_id=#{objectId} AND object_version=#{expectedVersion}
  AND lock_fence<=#{lockFence}

UPDATE aid_project_setting SET setting_value=#{settingValue},setting_version=setting_version+1,
  last_actor_user_id=#{actorUserId},update_time=NOW()
WHERE project_id=#{projectId} AND setting_key=#{settingKey} AND setting_version=#{expectedVersion}

mapper.select:
SELECT b.* FROM aid_canvas_task_binding b
WHERE b.status IN ('SUBMITTING','QUEUED','PENDING','PROCESSING')
ORDER BY b.update_time,b.id LIMIT #{limit}

SELECT * FROM aid_canvas_task_binding
WHERE workspace_id=#{workspaceId} AND object_id=#{objectId}
ORDER BY id DESC LIMIT #{offset},#{limit}

SELECT r.id AS resultId,r.task_id AS taskId,r.media_type AS mediaType,r.mime_type AS mimeType,
  c.id AS resourceId,b.input_object_version AS inputObjectVersion
FROM (
  SELECT task_id,input_object_version FROM aid_canvas_task_binding
  WHERE workspace_id=#{workspaceId} AND object_id=#{objectId}
    AND input_object_version > 0 AND input_object_version <= #{objectVersion}
    AND status='SUCCEEDED' AND task_id IS NOT NULL
  ORDER BY id DESC LIMIT #{limit}
) b
INNER JOIN aid_media_task t ON t.id=b.task_id AND t.status='SUCCEEDED'
INNER JOIN aid_media_result r ON r.task_id=b.task_id
LEFT JOIN aid_canvas_resource c ON c.workspace_id=#{workspaceId}
  AND c.source_type='MEDIA_RESULT' AND c.source_id=r.id AND c.status='ACTIVE'
ORDER BY r.task_id,r.result_index,r.id

mapper.update:
UPDATE aid_canvas_resource SET metadata_json=#{resource.metadataJson},file_size=#{resource.fileSize},
  mime_type=#{resource.mimeType},update_time=NOW()
WHERE id=#{resource.id} AND workspace_id=#{resource.workspaceId} AND owner_user_id=#{resource.ownerUserId}
  AND status='ACTIVE' AND media_type=#{resource.mediaType} AND storage_url=#{resource.storageUrl}
  AND metadata_json <=> #{expectedMetadataJson}

UPDATE aid_canvas_node_draft SET draft_version=draft_version+1,base_object_version=#{baseObjectVersion},
  draft_json=#{draftJson},draft_hash=#{draftHash},update_time=NOW()
WHERE workspace_id=#{workspaceId} AND object_id=#{objectId} AND user_id=#{userId}
  AND draft_version=#{expectedVersion}

mapper.select:
SELECT id,operator,operator_name AS operatorName,target_type AS targetType,target_id AS targetId,
  target_user_id AS targetUserId,action,detail_json AS detail,create_time AS createTime
FROM aid_canvas_audit_log WHERE 1=1
AND operator=#{operator}
AND target_user_id=#{targetUserId}
AND action=#{action}
ORDER BY id DESC
